-- MySQL scale fixture based on Datly's VENDOR/PRODUCT relation pattern.
CREATE DATABASE IF NOT EXISTS reporting_e2e;
USE reporting_e2e;
DROP TABLE IF EXISTS STUDIO_WIDE_60;
DROP TABLE IF EXISTS STUDIO_NODE;
CREATE TABLE STUDIO_NODE (
  ID INT NOT NULL PRIMARY KEY,
  PARENT_ID INT NULL,
  NODE_KIND VARCHAR(32) NOT NULL,
  NAME VARCHAR(100) NOT NULL,
  LEVEL_NO INT NOT NULL,
  INDEX idx_studio_node_parent (PARENT_ID),
  CONSTRAINT fk_studio_node_parent FOREIGN KEY (PARENT_ID) REFERENCES STUDIO_NODE(ID)
);
